//! In-crate serialization tests (private fields are reachable here).
//! Serialization laws (ADR-003): determinism, bit-exact f64, ext preservation, golden fixture,
//! and rejection of every invariant violation. Fixtures are generated by the serializer itself:
//! run with `GIP_UPDATE_GOLDEN=1` to regenerate; never hand-edit `tests/golden/*.gip`.

use std::collections::BTreeMap;
use std::path::Path as FsPath;

use crate::file::{from_json, to_json};
use crate::path::{FillRule, HandleMode, PointType, Subpath, Vertex};
use crate::{
    AssetId, AssetRecord, Document, GipError, GipFile, Node, NodeId, NodeKind, Page, Path,
    Transform,
};

const SALT: u32 = 0x00ab_12cd;

fn id(counter: u64) -> NodeId {
    NodeId::compose(SALT, counter).unwrap()
}

fn transform(x: f64, y: f64, w: f64, h: f64) -> Transform {
    Transform {
        x,
        y,
        w,
        h,
        rotation_deg: 0.0,
        flip_h: false,
        flip_v: false,
    }
}

/// A representative document: page → frame → (rectangle, vector path). Exercises every
/// persisted field kind, a rotated node, an asset, and an unknown key preserved via ext.
fn sample() -> GipFile {
    let mut file = GipFile::new("Sample", SALT);
    let (frame, rect, path_node) = (id(2), id(3), id(4));
    let mut frame_node = Node::new(NodeKind::Frame, "Card", transform(0.0, 0.0, 320.0, 200.0));
    frame_node.children = vec![rect, path_node];
    frame_node
        .ext
        .insert("x-future".into(), serde_json::json!({"keep": [1, 2.5]}));
    let rect_node = Node {
        opacity: 0.5,
        ..Node::new(
            NodeKind::Rectangle,
            "Surface",
            Transform {
                rotation_deg: 33.7,
                ..transform(8.0, 8.0, 0.1, 303.0)
            },
        )
    };
    let vertex = |x: f64, y: f64| Vertex {
        anchor: [x, y],
        handle_in: [x, y],
        handle_out: [x, y],
        point_type: PointType::Corner,
        handle_mode: HandleMode::Disconnected,
    };
    let path = Path {
        subpaths: vec![Subpath {
            vertices: vec![vertex(0.0, 0.0), vertex(1.0 / 3.0, 5e-324)],
            closed: true,
        }],
        fill_rule: FillRule::NonZero,
    };
    let path_node_data = Node {
        path: Some(path),
        ..Node::new(NodeKind::VectorPath, "Edge", transform(0.0, 0.0, 1.0, 1.0))
    };
    file.document = Document {
        pages: vec![Page {
            id: id(1),
            name: "Page 1".into(),
            children: vec![frame],
            ext: BTreeMap::new(),
        }],
        nodes: BTreeMap::from([
            (frame, frame_node),
            (rect, rect_node),
            (path_node, path_node_data),
        ]),
        ext: BTreeMap::new(),
    };
    file.meta.next_id = 6;
    file.assets.insert(
        AssetId::compose(SALT, 5).unwrap(),
        AssetRecord {
            hash: "0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcdef".into(),
            kind: "image".into(),
            bytes: 4096,
            missing: false,
            ext: BTreeMap::new(),
        },
    );
    file
}

#[test]
fn golden_fixture_matches_serializer_output() {
    let text = to_json(&sample()).unwrap();
    let path = FsPath::new(env!("CARGO_MANIFEST_DIR")).join("tests/golden/sample.gip");
    if std::env::var_os("GIP_UPDATE_GOLDEN").is_some() {
        std::fs::write(&path, &text).unwrap();
    }
    let golden =
        std::fs::read_to_string(&path).expect("run with GIP_UPDATE_GOLDEN=1 once to create it");
    assert_eq!(
        text, golden,
        "serializer output drifted from the golden fixture"
    );
}

#[test]
fn save_load_save_is_byte_identical() {
    let first = to_json(&sample()).unwrap();
    let second = to_json(&from_json(&first).unwrap()).unwrap();
    assert_eq!(first, second);
}

#[test]
fn ext_keys_survive_round_trip() {
    let loaded = from_json(&to_json(&sample()).unwrap()).unwrap();
    let frame = &loaded.document.nodes[&id(2)];
    assert_eq!(frame.ext["x-future"], serde_json::json!({"keep": [1, 2.5]}));
}

#[test]
fn f64_values_round_trip_bit_exact() {
    let values = [
        0.1,
        1.0 / 3.0,
        5e-324,
        f64::MAX,
        -0.0,
        1e-300,
        123_456.789_012_345_6,
        0.0,
    ];
    for v in values {
        let mut file = sample();
        let node = file.document.nodes.get_mut(&id(3)).unwrap();
        node.transform.x = v;
        let back = from_json(&to_json(&file).unwrap()).unwrap();
        let got = back.document.nodes[&id(3)].transform.x;
        assert_eq!(got.to_bits(), v.to_bits(), "value {v:e} changed bits");
    }
}

#[test]
fn non_finite_values_are_refused_before_writing() {
    let mut file = sample();
    file.document.nodes.get_mut(&id(3)).unwrap().transform.x = f64::NAN;
    assert!(matches!(to_json(&file), Err(GipError::Invalid(_))));
    let mut file = sample();
    file.document.nodes.get_mut(&id(3)).unwrap().opacity = f64::INFINITY;
    assert!(matches!(to_json(&file), Err(GipError::Invalid(_))));
}

#[test]
fn ids_are_written_as_16_hex_strings() {
    let text = to_json(&sample()).unwrap();
    assert!(text.contains("\"nextId\": \"0000000000000006\""));
    assert!(text.contains("\"docSalt\": \"0000000000ab12cd\""));
    assert!(text.contains(&format!("\"{:016x}\"", id(2).to_raw())));
}

fn rejects(file: GipFile, needle: &str) {
    match to_json(&file) {
        Err(GipError::Invalid(msg)) => {
            assert!(msg.contains(needle), "got {msg:?}, wanted {needle:?}")
        }
        other => panic!("expected invalid ({needle}), got {other:?}"),
    }
}

#[test]
fn rule_asset_ids_share_the_lineage_space() {
    let mut file = sample();
    file.assets.insert(
        AssetId::compose(SALT, 2).unwrap(),
        file.assets.values().next().unwrap().clone(),
    );
    rejects(file, "collides with a document id");
    let mut file = sample();
    file.meta.next_id = 5;
    rejects(file, "above nextId");
}

#[test]
fn rule_orphan_node_is_rejected() {
    let mut file = sample();
    file.meta.next_id = 10;
    file.document.nodes.insert(
        id(9),
        Node::new(NodeKind::Rectangle, "Lost", Transform::ZERO),
    );
    rejects(file, "orphan");
}

#[test]
fn rule_double_reference_is_rejected() {
    let mut file = sample();
    file.document.pages[0].children.push(id(2));
    rejects(file, "referenced 2 times");
}

#[test]
fn rule_dangling_child_is_rejected() {
    let mut file = sample();
    file.document
        .nodes
        .get_mut(&id(2))
        .unwrap()
        .children
        .push(id(77));
    rejects(file, "does not resolve");
}

#[test]
fn rule_foreign_salt_is_rejected() {
    let mut file = sample();
    file.meta.doc_salt = 0x0000_0001;
    rejects(file, "does not belong to lineage");
}

#[test]
fn rule_counter_must_stay_below_high_water_mark() {
    let mut file = sample();
    file.meta.next_id = 4;
    rejects(file, "at or above nextId");
}

#[test]
fn rule_children_only_on_containers() {
    let mut file = sample();
    file.document
        .nodes
        .get_mut(&id(3))
        .unwrap()
        .children
        .push(id(4));
    rejects(file, "cannot hold children");
}

#[test]
fn rule_path_payload_only_on_vector_path() {
    let mut file = sample();
    let path = file.document.nodes[&id(4)].path.clone();
    file.document.nodes.get_mut(&id(3)).unwrap().path = path;
    rejects(file, "only vector-path carries");
}

#[test]
fn rule_vector_path_requires_payload() {
    let mut file = sample();
    file.document.nodes.get_mut(&id(4)).unwrap().path = None;
    rejects(file, "requires a path payload");
}

#[test]
fn rule_transform_ranges() {
    let mut file = sample();
    file.document.nodes.get_mut(&id(3)).unwrap().transform.w = -1.0;
    rejects(file, "sizes must be");
    let mut file = sample();
    file.document
        .nodes
        .get_mut(&id(3))
        .unwrap()
        .transform
        .rotation_deg = -180.0;
    rejects(file, "outside (−180, 180]");
}

#[test]
fn rule_opacity_range() {
    let mut file = sample();
    file.document.nodes.get_mut(&id(3)).unwrap().opacity = 1.5;
    rejects(file, "opacity");
}

#[test]
fn rule_rotation_upper_bound_is_inclusive() {
    let mut file = sample();
    file.document
        .nodes
        .get_mut(&id(3))
        .unwrap()
        .transform
        .rotation_deg = 180.0;
    assert!(to_json(&file).is_ok());
}

#[test]
fn unknown_kind_and_bad_id_encoding_fail_to_load() {
    let text = to_json(&sample()).unwrap();
    assert!(matches!(
        from_json(&text.replace("\"rectangle\"", "\"blob\"")),
        Err(GipError::Json(_))
    ));
    let upper = text.replace(
        &format!("{:016x}", id(3).to_raw()),
        &format!("{:016X}", id(3).to_raw()),
    );
    assert!(matches!(from_json(&upper), Err(GipError::Json(_))));
}

#[test]
fn unknown_transform_key_is_rejected_not_silently_dropped() {
    let text = to_json(&sample())
        .unwrap()
        .replace("\"flipH\"", "\"skewX\": 0.0,\n \"flipH\"");
    assert!(matches!(from_json(&text), Err(GipError::Json(_))));
}

#[test]
fn format_and_version_gates() {
    let text = to_json(&sample()).unwrap();
    assert!(matches!(
        from_json(&text.replace("\"format\": \"gip\"", "\"format\": \"zip\"")),
        Err(GipError::UnsupportedFormat(_))
    ));
    assert!(matches!(
        from_json(&text.replace("\"version\": 1", "\"version\": 2")),
        Err(GipError::UnsupportedVersion(2))
    ));
}
